// M3 Dry-Run Preview — Step 5 dry-run gate (NOT a production route).
// Mirrors /m3-sample-preview but loads the 3 dry-run sims generated by
// `bulk_seed_sims.py --module 3 --dry-run`. Renders them via the same
// SpreadsheetSim component the live phase uses, so what you see here is
// what students will get on a real seed.
//
// Url:  /m3-dryrun-preview         → tab through all 3
//       /m3-dryrun-preview?s=3.5  → directly open one
//
// Cleanup: after Step 5 sign-off, this file + its data folder can be deleted.

import { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { adaptSimToWorkbook } from '@/components/simulations/excelSimAdapter';
import SpreadsheetSim from '@/components/simulations/SpreadsheetSim';

import s31 from '@/data/m3-dryrun/s3-1.json';
import s35 from '@/data/m3-dryrun/s3-5.json';
import s39 from '@/data/m3-dryrun/s3-9.json';
import s39Complete from '@/data/m3-dryrun/s3-9-completed.json';

const ALL = [
  { key: '3.1', label: '3.1 · early', tag: 'foundational',
    accent: '#3B82F6', icon: 'E', sample: s31 },
  { key: '3.5', label: '3.5 · mid',   tag: 'logic',
    accent: '#A855F7', icon: 'M', sample: s35 },
  { key: '3.9', label: '3.9 · late',  tag: 'pivots · empty',
    accent: '#10B981', icon: 'L', sample: s39 },
  { key: '3.9c', label: '3.9 · scored', tag: 'pivots · filled',
    accent: '#F59E0B', icon: 'S', sample: s39Complete },
];

function workbookFromSample(sample) {
  return adaptSimToWorkbook({
    title: sample.title,
    config: {
      multi_tab_excel_workbook: sample.multi_tab_excel_workbook,
      expected_answers: sample.expected_answers,
      instructions: sample.instructions,
    },
  });
}

export default function M3DryRunPreview() {
  const [searchParams, setSearchParams] = useSearchParams();
  const initial = ALL.findIndex((x) => x.key === searchParams.get('s'));
  const [tab, setTab] = useState(initial >= 0 ? initial : 0);
  const current = ALL[tab];
  const workbook = useMemo(() => workbookFromSample(current.sample), [current]);

  useEffect(() => {
    setSearchParams({ s: current.key });
  }, [current.key, setSearchParams]);

  const ea = current.sample.expected_answers;
  const totalPoints = Object.values(ea).reduce((s, v) => s + (v.points || 0), 0);
  const hints = current.sample.hints || [];

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-white p-4 sm:p-8" data-testid="m3-dryrun-preview">
      <div className="flex items-center gap-3 mb-6 flex-wrap" data-testid="dryrun-tabs">
        <h1 className="font-clash text-2xl font-semibold mr-4">M3 Dry-Run Preview — Step 5</h1>
        <span className="font-mono text-[10px] uppercase tracking-[0.2em] text-amber-300 px-2 py-1 rounded border border-amber-500/40 bg-amber-500/10">DRY · NO DB WRITES</span>
        {ALL.map((s, i) => (
          <button
            key={s.key}
            onClick={() => setTab(i)}
            data-testid={`dryrun-tab-${s.key.replace('.', '-')}`}
            className={`px-4 py-2 rounded-xl font-mono text-xs border transition-all ${
              i === tab ? 'border-transparent text-black shadow-lg'
                        : 'border-white/15 text-white/60 hover:border-white/40 hover:text-white'
            }`}
            style={i === tab ? { backgroundColor: s.accent } : undefined}
          >
            <span className="mr-2 font-bold">{s.icon}</span>{s.label} · {s.tag}
          </button>
        ))}
      </div>

      <div className="rounded-2xl border border-white/10 bg-white/[0.02] p-6 mb-6" data-testid="dryrun-header">
        <div className="flex items-center justify-between gap-4 mb-3 flex-wrap">
          <div>
            <div className="text-xs font-mono uppercase tracking-[0.2em] text-white/40">Session {current.key} · {current.tag}</div>
            <div className="font-clash text-xl font-semibold mt-1">{current.sample.title}</div>
            <div className="text-sm text-white/60 mt-1">{current.sample.scenario}</div>
          </div>
          <div className="flex items-center gap-3 text-xs font-mono">
            <span className="px-3 py-1 rounded-full bg-white/[0.06] border border-white/10">
              <span className="text-white/40">Points </span>
              <span className="text-white font-semibold">{totalPoints}</span>
            </span>
            <span className="px-3 py-1 rounded-full bg-white/[0.06] border border-white/10">
              <span className="text-white/40">Questions </span>
              <span className="text-white font-semibold">{Object.keys(ea).length}</span>
            </span>
            <span className="px-3 py-1 rounded-full bg-white/[0.06] border border-white/10">
              <span className="text-white/40">Hints </span>
              <span className="text-white font-semibold">{hints.length}</span>
            </span>
          </div>
        </div>
        <div className="mt-3 text-xs text-white/60">
          <span className="text-white/40 font-mono uppercase tracking-[0.15em]">Objective: </span>
          {current.sample.learning_objective}
        </div>
      </div>

      <div className="rounded-2xl border border-white/10 bg-white/[0.02] p-4 mb-6" data-testid="dryrun-workspace">
        <SpreadsheetSim
          workbook={workbook}
          onAutoSave={async () => {}}
          onSubmit={async () => {}}
        />
      </div>

      <div className="grid lg:grid-cols-2 gap-4">
        <div className="rounded-2xl border border-white/10 bg-white/[0.02] p-6" data-testid="dryrun-hints">
          <div className="font-mono text-xs uppercase tracking-[0.2em] text-white/40 mb-3">
            Hints (progressive)
          </div>
          {hints.map((h, i) => (
            <div key={i} className="flex items-start gap-3 mb-3">
              <div className="font-mono text-xs text-white/40 w-6 shrink-0">{i + 1}.</div>
              <div className="text-sm text-white/80">{h}</div>
            </div>
          ))}
        </div>
        <div className="rounded-2xl border border-white/10 bg-white/[0.02] p-6" data-testid="dryrun-answers">
          <div className="font-mono text-xs uppercase tracking-[0.2em] text-white/40 mb-3">
            {current.sample.multi_tab_excel_workbook?.sheets?.some((s) => s.kind === 'pivot')
              ? 'Pivot grading spec'
              : 'Expected answers'}
          </div>
          {current.sample.multi_tab_excel_workbook?.sheets?.some((s) => s.kind === 'pivot') ? (
            (() => {
              const pivotSheet = current.sample.multi_tab_excel_workbook.sheets.find((s) => s.kind === 'pivot');
              const exp = pivotSheet?.spec?.expected_state || {};
              const expCells = pivotSheet?.spec?.expected_cells || [];
              return (
                <div className="space-y-3">
                  <div className="rounded border border-white/5 bg-white/[0.02] p-3">
                    <div className="text-[10px] font-mono uppercase tracking-wider text-white/40 mb-1.5">Expected zones</div>
                    <div className="text-xs text-white/80 font-mono space-y-0.5">
                      <div><span className="text-white/40">rows:</span> {(exp.rows || []).join(', ') || '—'}</div>
                      <div><span className="text-white/40">cols:</span> {(exp.columns || []).join(', ') || '—'}</div>
                      <div><span className="text-white/40">vals:</span> {(exp.values || []).map((v) => `${v.agg}(${v.field})`).join(', ') || '—'}</div>
                    </div>
                  </div>
                  <div className="rounded border border-white/5 bg-white/[0.02] p-3">
                    <div className="text-[10px] font-mono uppercase tracking-wider text-white/40 mb-1.5">Expected pivot cells</div>
                    <div className="text-xs text-white/80 font-mono space-y-1">
                      {expCells.map((c, i) => (
                        <div key={i}>
                          <span className="text-white/50">{c.row_label} × {c.col_label}</span>
                          <span className="text-emerald-300 ml-2">→ {Number(c.value).toLocaleString('en-IN')}</span>
                          <span className="text-white/30 ml-2">±{c.tolerance}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              );
            })()
          ) : (
            <div className="space-y-2">
              {Object.entries(ea).map(([key, spec], i) => (
                <div key={key} className="flex items-start gap-3 p-2 rounded border border-white/5 bg-white/[0.02]">
                  <div className="font-mono text-xs text-white/40 w-6 shrink-0">{i + 1}</div>
                  <div className="flex-1 min-w-0">
                    <code className="text-xs text-emerald-300 font-mono break-all">{spec.formula_pattern}</code>
                    <div className="text-xs text-white/50 mt-1">
                      → <span className="text-white font-semibold">{JSON.stringify(spec.expected_value)}</span>
                      <span className="text-white/30 ml-3">{spec.points}pt</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
